"""Content-addressed strategy packets. A run freezes the full module catalog."""
from dataclasses import dataclass
from pathlib import Path
import copy,hashlib,json,os

ROOT=Path(__file__).resolve().parent.parent

def digest(value):return hashlib.sha256(json.dumps(value,sort_keys=True,separators=(',',':')).encode()).hexdigest()

@dataclass(frozen=True)
class StrategyModule:
    id:str
    name:str
    version:str
    priority:int
    match:dict
    prompt:str
    rationale:str
    category:str="Other decisions"
    act:int=0
    region:str="All acts / fallback"
    encounter:str=""
    def matches(self,obs):
        state=obs['state'];game=state.get('game',state)
        enemies={e.get('creature',{}).get('name','') for e in game.get('enemies') or []}
        for key,value in self.match.items():
            if key=='kind' and obs['kind'] not in value:return False
            if key=='room' and game.get('room') not in value:return False
            if key=='enemy_any' and not enemies.intersection(value):return False
            if key=='min_enemies' and len(game.get('enemies') or [])<value:return False
            if key=='event_id' and state.get('event_id',game.get('event_id')) not in value:return False
        return True

class Strategy:
    def __init__(self,packet):
        self._packet=copy.deepcopy(packet)
        self.modules=tuple(StrategyModule(**m) for m in packet['modules'])
        if len({m.id for m in self.modules})!=len(self.modules):raise ValueError('Duplicate strategy module')
        for m in self.modules:
            if set(m.match)-{'kind','room','enemy_any','min_enemies','event_id'}:raise ValueError('Unknown strategy matcher')
        self.sha256=digest(self._packet)
    @classmethod
    def load(cls,goal=None,profile='balanced'):
        packet=version_packet(os.environ.get('DEALMAKER_STRATEGY_VERSION','1.1.0'))
        if goal is not None:packet['goal']=goal
        packet['profile']=profile
        # Freeze actual prompt-generation source as well as prose; later edits must
        # not retroactively change which packet a historical run reports.
        packet['prompt_builder']={name:(ROOT/'scripts'/name).read_text() for name in ('decision_prompts.py','strategy_registry.py','compact_decisions.py','decision_memory.py','jev_playtest.py')}
        return cls(packet)
    @property
    def packet(self):return copy.deepcopy(self._packet)
    def save(self,path):
        path=Path(path)
        with path.open('x') as f:json.dump({'sha256':self.sha256,'packet':self._packet},f,indent=2)
    def select(self,obs):
        matches=sorted((m for m in self.modules if m.matches(obs)),key=lambda m:(-m.priority,m.id))
        if not matches:raise ValueError('No strategy fallback for '+obs['kind'])
        module=matches[0]
        return module,{'packet_sha256':self.sha256,'strategy_id':self._packet['id'],'strategy_version':self._packet['version'],
                       'module_id':module.id,'module_version':module.version,'route':'deterministic','matched':module.match}
    def prompt(self,obs,character=None):
        module,selection=self.select(obs)
        advice=self._packet.get('character_advice',{}).get(character,{})
        game=obs['state'].get('game',obs['state'])
        held={p.get('id') for p in game.get('potions',[]) if p}
        additions=[]
        if obs['kind']=='combat' and self._packet.get('combat_basics'):
            additions.append(self._packet['combat_basics'])
        if held and obs['kind'] in {'combat','rewards','shop','map'} and advice:
            additions.append(advice['potion_policy'])
            if obs['kind']=='combat':
                additions += [g['advice'] for g in advice['groups'] if held.intersection(g['ids'])]
        turn_advice=self._packet.get('turn_advice',{})
        if obs['kind']=='combat' and turn_advice:
            incoming=sum(i.get('total_damage',0) for e in game.get('enemies') or [] for i in e.get('intents',[]))
            energy=game.get('energy',0)
            hand=[h['card'] for h in game.get('hand') or []]
            slippery=any(p.get('id')=='SLIPPERY_POWER' and p.get('amount',0)>0 for e in game.get('enemies') or [] for p in e['creature'].get('powers',[]))
            block_available=any(a['option'].get('action')=='play_card' and a['option'].get('card',{}).get('variables',{}).get('Block',0)>0 for a in obs['actions'])
            if slippery and turn_advice.get('slippery'):additions.append(turn_advice['slippery'])
            elif not block_available and turn_advice.get('no_block'):additions.append(turn_advice['no_block'])
            elif incoming==0:additions.append(turn_advice['no_incoming'])
            elif incoming>game.get('player',{}).get('block',0):
                additions.append(turn_advice['one_energy'] if energy==1 else turn_advice['under_attack'])
            bash=next((c for c in hand if c.get('id')=='BASH'),None)
            if bash and not (slippery and turn_advice.get('slippery')) and any(c is not bash and c.get('type')=='Attack' and isinstance(c.get('cost'),(int,float)) and isinstance(bash.get('cost'),(int,float)) and 0<=c['cost']<=energy-bash['cost'] for c in hand):
                additions.append(turn_advice['bash_setup'])
        # Only visible, immediately relevant objects trigger definitions: never the whole deck.
        if self._packet.get('mechanic_hints'):
            import re
            objects=[a.get('option',{}) for a in obs.get('actions',[])]
            objects.append(obs['state'].get('source') or {})
            if obs['kind']=='combat':
                objects += [h['card'] for h in game.get('hand') or []]
                objects += list(game.get('potions') or [])
                objects += list(game.get('player',{}).get('powers') or [])
                objects += [p for e in game.get('enemies') or [] for p in e.get('creature',{}).get('powers') or []]
            if obs['kind']=='combat' and self._packet.get('current_turn_hints'):
                opts=[a['option'] for a in obs.get('actions',[])]
                block_cards=[o for o in opts if o.get('action')=='play_card' and (o.get('card') or {}).get('variables',{}).get('Block',0)>0]
                incoming=sum(i.get('total_damage',0) for e in game.get('enemies') or [] for i in e.get('intents',[]))
                if 'SPEED_POTION' in held and not block_cards:
                    additions.append(self._packet['current_turn_hints']['no_speed_target'])
                if 'WEAK_POTION' in held and incoming-game.get('player',{}).get('block',0)>=20:
                    additions.append(self._packet['current_turn_hints']['large_attack_weak'])
            visible=json.dumps(objects).lower()
            for hint in self._packet['mechanic_hints']:
                if obs['kind'] in hint['kinds'] and any(re.search(r'(?<![a-z])'+re.escape(term)+r'(?![a-z])',visible) for term in hint['terms']):
                    additions.append(hint['text'])
        plan=obs.get('run_plan',{})
        if obs['kind'] in {'card_reward','choose_card','bundle','shop','rest','map','upgrade'}:
            boss_advice=self._packet.get('boss_plans',{}).get(plan.get('known_boss'))
            if boss_advice:additions.append(boss_advice)
        selection['addenda']=additions
        return '\n'.join([self._packet['goal'],module.prompt,*additions]),selection

def version_packet(version):
    import re
    if not re.fullmatch(r'\d+\.\d+\.\d+',version):raise ValueError('Invalid strategy version')
    return json.loads((ROOT/'strategies/balanced'/f'{version}.json').read_text())

def require_approved(version=None):
    packet=version_packet(version or os.environ.get('DEALMAKER_STRATEGY_VERSION','1.1.0'))
    approvals=json.loads((ROOT/'strategies/approvals.json').read_text())
    if digest(packet) not in approvals:raise ValueError('Strategy is not approved. Review its diff before authorizing a run.')

def strategy_diff(before,after):
    import difflib
    a=version_packet(before);b=version_packet(after)
    def display(value):
        return value if isinstance(value,str) else json.dumps(value,indent=2) if value is not None else ''
    def field_diff(key,left,right):
        import re
        l=re.findall(r'\s+|[^\s]+',display(left));r=re.findall(r'\s+|[^\s]+',display(right))
        ls=[];rs=[]
        for tag,i,j,x,y in difflib.SequenceMatcher(None,l,r,autojunk=False).get_opcodes():
            ls.append({'text':''.join(l[i:j]),'changed':tag!='equal'})
            rs.append({'text':''.join(r[x:y]),'changed':tag!='equal'})
        return {'field':key,'left':ls,'right':rs}
    sections=[]
    package=[field_diff(k,a.get(k),b.get(k)) for k in ('name','version','description','goal','prompt_format') if a.get(k)!=b.get(k)]
    if package:sections.append({'id':'package','name':'Package details','status':'modified','metadata':True,'fields':package})
    for key,name in [('current_turn_hints','Current-turn potion tactics'),('mechanic_hints','Conditional mechanic definitions and tactics'),('planning_context','Run-planning context enabled'),('boss_plans','Boss-specific drafting and potion plans'),('turn_advice','Turn-specific advice routing'),('combat_basics','Combat decision fundamentals'),('observation_policy','Observed decision history'),('character_advice','Ironclad potion priorities'),('compression_contract','Context compression and tradeoffs')]:
        if a.get(key)!=b.get(key):sections.append({'id':key,'name':name,'status':'modified','fields':[field_diff(key,a.get(key),b.get(key))]})
    left={m['id']:m for m in a['modules']};right={m['id']:m for m in b['modules']}
    unchanged=0
    for key in dict.fromkeys([*right,*left]):
        l=left.get(key,{});r=right.get(key,{})
        if l==r:unchanged+=1;continue
        fields=[field_diff(k,l.get(k),r.get(k)) for k in ('prompt','rationale','match','priority','name','version','category','act','region','encounter') if l.get(k)!=r.get(k)]
        sections.append({'id':key,'name':r.get('name',l.get('name',key)),'status':'added' if not l else 'removed' if not r else 'modified','fields':fields})
    return {'before':before,'after':after,'sections':sections,'unchanged_modules':unchanged,
            'diff':'\n'.join(difflib.unified_diff(json.dumps(a,indent=2).splitlines(),json.dumps(b,indent=2).splitlines(),fromfile=before,tofile=after,lineterm=''))}

def catalog():
    active=Strategy.load();entries=[]
    approvals=json.loads((ROOT/'strategies/approvals.json').read_text())
    for path in sorted((ROOT/'strategies/balanced').glob('*.json'),reverse=True):
        p=json.loads(path.read_text());sha=active.sha256 if p['version']==active.packet['version'] else digest(p)
        entries.append({**p,'sha256':sha,'approval':approvals.get(digest(p)),
          'selection_order':['Exact encounter','Encounter group','Boss / elite / normal fallback','Decision-type fallback','Generic fallback'],
          'model_router':{'enabled':False}})
    return entries

prompt_builder.compact_decisions.py:
"""Decision-v3. Stateless compact observations; raw trace/actions remain untouched."""
import json,re
from collections import Counter
from decision_prompts import clean, project

VERSION='decision-v3'

def label(value):
    return str(value).removesuffix('_POWER').replace('_',' ').title()

def readable(value):
    if isinstance(value,str):
        return re.sub(r'\[img\]([^[]+)\[/img\]',lambda m:'1 Energy' if 'energy_icon' in m[1] else 'icon '+m[1].split('/')[-1].split('.')[0],value)
    if isinstance(value,list):return [readable(v) for v in value]
    if isinstance(value,dict):return {k:readable(v) for k,v in value.items()}
    return value

def build(obs, strategy, character, rules):
    projected=project(obs)
    game=projected['state']
    combat=obs['kind']=='combat' or (obs['kind'] in {'card_selection','simple_select'} and 'enemies' in game)
    definitions={}; refs={}
    def card(c):
        # Target-specific effects stay separate when text differs. Never merge by name alone.
        d=clean({k:c[k] for k in ('name','cost','type','text','keywords') if k in c})
        if '{' in d.get('text',''):d['variables']=c.get('variables',{})
        key=json.dumps(d,sort_keys=True)
        if key not in refs:
            ref='c'+str(len(refs));refs[key]=ref;definitions[ref]=d
        return refs[key]
    def compact(v):
        if isinstance(v,list):return [compact(x) for x in v]
        if not isinstance(v,dict):return v
        if {'name','type','text','cost'}<=v.keys():return {'card':card(v)}
        return {k:compact(x) for k,x in clean(v).items()}
    if combat:
        for pile in ('draw_pile_unordered','discard','exhaust'):
            if pile in game:
                counts=Counter()
                for entry in game[pile]:counts[entry['card']['name']]+=entry['count']
                game[pile]=dict(counts)
        # These resources belong to the mod, not base Ironclad.
        if character=='ironclad':
            for k in ('boast','boast_attacks','stars','orb_slots','orbs_in_order','osty'):game.pop(k,None)
        # Hand index remains the exact engine index, including duplicates.
        game['hand']={str(h['index']):card(h['card']) for h in game.get('hand',[])}
    actions={}
    for a in obs['actions']:
        op=clean(dict(a['option'])); kind=op.get('action')
        if kind=='play_card':
            c=op.get('card',{});target=op.get('enemy_index',-1)
            # Card definitions preserve modified costs and full current effect text.
            value={'play':op['hand_index'],'card':card(c)}
            if target>=0:value['enemy']=target
            damage=c.get('preview_damage_per_hit')
            if damage is not None:value['damage_before_hp_caps']=damage
            actions[a['id']]='h'+str(value['play'])+((' '+value['card']) if game.get('hand',{}).get(str(value['play']))!=value['card'] else '')+((' -> e'+str(target)) if target>=0 else '')+(('; hit '+str(damage)) if damage is not None else '')
            if obs.get('context_policy') == 'observed-history-v1':
                enemy=next((e for e in game.get('enemies',[]) if e['index']==target),None)
                target_text=''
                if enemy:
                    creature=enemy['creature']
                    target_text=f" Target e{target}: HP {creature['hp']}, Block {creature.get('block',0)}; current hit {damage} before caps."
                actions[a['id']]=f"Play {c.get('name')} (hand {op['hand_index']}, cost {c.get('cost')}): {c.get('text','')}"+target_text
        elif kind in {'use_potion','discard_potion'}:
            value={'action':kind,'slot':op['slot'],'effect':op.get('text'),'potion':op.get('id')}
            if op.get('enemy_index',-1)>=0:value['enemy']=op['enemy_index']
            elif op.get('target'):value['target']='self'
            actions[a['id']]=kind+' slot '+str(op['slot'])+' '+label(op.get('id'))+((' on enemy '+str(op['enemy_index'])) if op.get('enemy_index',-1)>=0 else '')
        elif kind=='end_turn':actions[a['id']]='end turn'
        else:
            if obs.get('context_policy') == 'observed-history-v1':
                if kind=='claim_reward' and op.get('type')=='CardReward':
                    op['text']='Inspect free card offers; adds no card yet. You may Skip after inspection.'
                if kind=='proceed' and obs['kind']=='rewards':
                    op['text']='Leave remaining rewards.'
            actions[a['id']]=compact(op)
            if obs.get('context_policy') == 'observed-history-v1' and kind=='claim_reward' and op.get('type')=='CardReward' and obs.get('observed_history'):
                actions[a['id']]['history']='Card offers were already inspected and declined here. Reopening is not a reroll.'
    context=compact(game)
    if combat:
        # Compact text avoids repeating JSON scaffolding; values and power rules remain.
        def creature(c):
            base=f"HP {c.get('hp')}/{c.get('max_hp','?')} Block {c.get('block',0)}"
            powers=['%s %s: %s'%(label(p.get('id')),p.get('amount'),p.get('text','')) for p in c.get('powers',[])]
            return base+(' | '+'; '.join(powers) if powers else '')
        lines=[f"You: {creature(game.get('player',{}))}",f"Energy {game.get('energy')} Turn {game.get('turn')}",
               'Hand '+', '.join(f'h{i}={ref}' for i,ref in game.get('hand',{}).items())]
        if obs.get('context_policy') == 'observed-history-v1':
            incoming=sum(i.get('total_damage',0) for e in game.get('enemies',[]) for i in e.get('intents',[]))
            lines.insert(0,f"TOTAL enemy attack damage this turn: {incoming}. Current Block: {game.get('player',{}).get('block',0)}.")
        for e in game.get('enemies',[]):
            c=e['creature'];intents='; '.join(' '.join(f'{k}={v}' for k,v in i.items()) for i in e.get('intents',[]))
            lines.append(f"e{e['index']} {c['name']}: {creature(c)} | {intents}")
        for pile in ('draw_pile_unordered','discard','exhaust'):
            if game.get(pile):lines.append(pile+': '+', '.join(f'{name} x{n}' for name,n in game[pile].items()))
        if game.get('relics'):lines.append('Relics: '+'; '.join(f"{label(r['id'])}: {r.get('text','')}" for r in game['relics']))
        if game.get('potions'):lines.append('Potions: '+'; '.join(f"{label(p.get('id'))}: {p.get('text','')}" for p in game['potions'] if p))
        # Preserve less common resources and selection constraints without guessing meanings.
        other={k:v for k,v in context.items() if k not in {'player','energy','turn','hand','enemies','draw_pile_unordered','discard','exhaust','relics','potions'}}
        if other:lines.append(json.dumps(other,separators=(',',':')))
        context='\n'.join(lines)
    # Effects once per distinct card; no repeated JSON field names in each definition.
    definitions={ref:f"{d['name']} | {d['cost']} energy | {d['type']} | {d.get('text','')}"+((' | '+','.join(d['keywords'])) if d.get('keywords') else '')+((' | variables '+json.dumps(d['variables'])) if d.get('variables') else '') for ref,d in definitions.items()}
    result={'rules':'Hidden draws/RNG unknown.' if character=='ironclad' else rules,'strategy':strategy,'format':VERSION+'; h=hand,e=enemy; hit=damage before HP caps; piles unordered; absent lists empty.',
            'cards':definitions,'kind':obs['kind'],'state':context}
    if obs.get('run_plan'):result['run_plan']=obs['run_plan']
    if obs.get('observed_history'):result['history']=obs['observed_history']
    return readable(result),readable(actions)

prompt_builder.decision_memory.py:
"""Small factual history for a stateless pilot; never chooses or hides actions."""
import copy

class DecisionMemory:
    def __init__(self, planning=False):
        self.planning = planning
        self.seen_elites = set()
        self.act = None
        self.room = None
        self.declined = []

    def enrich(self, obs):
        game = obs['state'].get('game', obs['state'])
        room = (game.get('act'), game.get('floor'))
        if room != self.room:
            self.room, self.declined = room, []
        if self.act != game.get('act'):
            self.act = game.get('act')
            self.seen_elites.clear()
        if self.planning and obs['kind']=='combat' and game.get('room')=='Elite':
            self.seen_elites.update(e['creature']['name'] for e in game.get('enemies') or [])
        result = copy.deepcopy(obs)
        if self.planning:
            result['planning_context']=True
            if obs['kind'] in {'card_reward','choose_card','bundle','shop','rest','map','event','upgrade','card_selection','rewards'}:
                plan={k:game[k] for k in ('known_boss','potion_slots_free') if k in game}
                if self.seen_elites:plan['seen_elite_enemies_this_act']=sorted(self.seen_elites)
                if plan:result['run_plan']=plan
        if self.declined and obs['kind'] in {'rewards', 'card_reward'}:
            result['observed_history'] = {'declined_card_offers_this_room': self.declined,
                'meaning': 'These offers were inspected and skipped already. Reopening the same reward does not reroll it. Other rewards may differ.'}
        return result

    def observe(self, obs, chosen):
        self.enrich(obs)  # Also resets when called during prefix reconstruction.
        action = next(a['option'] for a in obs['actions'] if a['id'] == chosen)
        if obs['kind'] == 'card_reward' and action.get('action') in {'skip', 'reward_alternative'} and 'skip' in action.get('text', 'skip').lower():
            offer = [a['option']['card'].get('name', a['option']['card'].get('id'))
                     for a in obs['actions'] if isinstance(a['option'].get('card'), dict)]
            if offer and offer not in self.declined:
                self.declined.append(offer)

